def parity_inside(g, path):
    h,w=len(g),len(g[0]); ins=set()
    for y in range(h):
        for x in range(w):
            if g[y][x]==0:
                cnt=sum(1 for xx in range(x+1,w) if (y,xx) in path)
                if cnt%2==1: ins.add((y,x))
    return ins
